    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - 2 + √2 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> - √2 + x + <span class=\"frac\"><span class=\"num\">61</span><span class=\"den\">30</span></span> - √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = x + (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - 2 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">61</span><span class=\"den\">30</span></span>) + (√2 - √2 - √2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = x + 1 - √2</span>"}],
