    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: C = -(-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2)</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2 = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √2 - (-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √2 - (-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2) = <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">6</span></span> - 2√2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">6</span></span> - 2√2</span>"}],
