    enonce: "أوجد العدد الحقيقي y إذا علمت أنّ D و <span dir=\"ltr\" class=\"expr\">-1 - π</span> متساويان علما أنّ <span dir=\"ltr\" class=\"expr\">D = y + 4 - √3</span>",
    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">D = -1 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">y + 4 - √3 = -1 - π</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = -1 - π - (4 - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-1 - π - (4 - √3) = -5 + √3 - π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = -5 + √3 - π</span>"}],
