    correction: [{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r ؛</span> و إذا كان r سالبا فلا حلّ"},{"quoi":"نكتب ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">D - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> = y + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - √3</span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">y + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - √3 = 5</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> + √3</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\">y + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - √3 = -5</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">4</span></span> + √3</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن اثنان"}],
