    enonce: "أوجد <span dir=\"ltr\" class=\"expr\">|x|</span> إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">C - 5 = √3</span> علما أنّ <span dir=\"ltr\" class=\"expr\">C = x - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span>",
    correction: [{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> + √2 = √3</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> - √2 + √3</span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> - √2 + √3</span> هو عدد موجب تقريبا يساوي 7.98"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|x| = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> - √2 + √3</span>"}],
