    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: E = -(-a + <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span>)</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">a - b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - π = a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span></span>"},{"quoi":"نعزل b","math":"<span dir=\"ltr\" class=\"expr\">-b = a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span> - (a + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span> - (a + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - π) = -<span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">21</span></span> + π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">21</span></span> - π</span>"}],
