    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -2 + a - 2 + 1 - b + π + b - π - b + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-b + b - b) + (-2 - 2 + 1 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span>) + (π - π + π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = a - b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π</span>"}],
