    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: E = -(-a + <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span>)</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">a - b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π = a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span></span>"},{"quoi":"نعزل b","math":"<span dir=\"ltr\" class=\"expr\">-b = a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span> - (a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">a - <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">7</span></span> - (a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π) = -<span class=\"frac\"><span class=\"num\">61</span><span class=\"den\">35</span></span> - π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">61</span><span class=\"den\">35</span></span> + π</span>"}],
