    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">E = -b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">a - b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π = -b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - π</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = -b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - π - (-b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - π - (-b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + π) = <span class=\"frac\"><span class=\"num\">41</span><span class=\"den\">15</span></span> - 2π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">41</span><span class=\"den\">15</span></span> - 2π</span>"}],
