    correction: [{"quoi":"نحدّد إشارة ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">-1 + √3</span> عدد موجب تقريبا يساوي 0.73"},{"quoi":"نزيل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-1 + √3| = -1 + √3</span>"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -1 + √3 + 2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> + y - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - x - 2y + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">10</span></span> + 2√3</span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة معا و الأعداد الصمّاء معا"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -x - y - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + 2√3</span>"}],
