    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - a + 1 - b + 2 + 4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + π + 2a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span> - 2π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + 2a) - b + (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 1 + 2 + 4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span>) + (π - 2π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - 1 - π</span>"}],
