    enonce: "جد العدد الحقيقي x بحيث: <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + [x + (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)] + (-2 - x) + x - <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">6</span></span> = 4 + √2</span>",
    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + [x + (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)] + (-2 - x) + x - <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">6</span></span> = x - 4 - √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">x - 4 - √2 = 4 + √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = 4 + √2 - (-4 - √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 + √2 - (-4 - √2) = 8 + 2√2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 8 + 2√2</span>"}],
