    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-y + [y + (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)] + [-2 + 9 + √5] + y - <span class=\"frac\"><span class=\"num\">63</span><span class=\"den\">10</span></span> = y + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + √5</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">y + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + √5 = -2</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = -2 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + √5)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-2 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + √5) = -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span> - √5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span> - √5</span>"}],
