    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(a + 1) + [-π - (6 + 2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span>)] + a - a + <span class=\"frac\"><span class=\"num\">263</span><span class=\"den\">30</span></span> + 2π = a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - π</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - π - (<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - π - (<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π) = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> - 2π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> - 2π</span>"}],
