    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = -π + 1 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 1 + b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + 3a + b - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">12</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = 3a + (b + b) + (1 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 1 + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">12</span></span>) - π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 3a + 2b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - π</span>"}],
