    correction: [{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">18</span><span class=\"den\">5</span></span> = 5</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">|b| = 5</span>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">b = 5</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">b = -5</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن متقابلان"}],
