    correction: [{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span> = 3</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">|b| = 3</span>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">b = 3</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">b = -3</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن متقابلان"}],
